// UserAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func UserAuditing(policy UserAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[User]()
		if err != nil {
			return err
		}
		return RegisterUserObserver(registrar, pool, NewUserObserver(name), func(resolver foundation.Resolver) (func() UserHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() UserHooks {
				write := func(ctx context.Context, tx *database.Tx, changes UserChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return UserHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
